import os
import sqlite3

import stripe
from agents import function_tool

stripe.api_key = os.environ["STRIPE_SECRET_KEY"]
DB_PATH = os.environ.get("TICKETING_DB", "/var/lib/ticketing/orders.db")
VALID_REASONS = {"requested_by_customer", "duplicate", "fraudulent"}


@function_tool
def cancel_order_and_refund(order_id: str, reason: str = "requested_by_customer", refund_amount_cents: int = 0) -> dict:
    if reason not in VALID_REASONS:
        return {"ok": False, "error": f"reason must be one of {sorted(VALID_REASONS)}"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        order = conn.execute(
            "SELECT id, status, total_cents, payment_intent_id FROM orders WHERE id = ?",
            (order_id,),
        ).fetchone()
        if order is None:
            return {"ok": False, "error": f"order {order_id} not found"}
        if order["status"] == "cancelled":
            return {"ok": False, "error": "order already cancelled"}

        amount = refund_amount_cents or order["total_cents"]
        if amount <= 0 or amount > order["total_cents"]:
            return {"ok": False, "error": "refund amount must be between 1 and the order total"}

        refund = stripe.Refund.create(
            payment_intent=order["payment_intent_id"],
            amount=amount,
            reason=reason,
            metadata={"order_id": order_id},
        )

        with conn:
            voided = conn.execute(
                "DELETE FROM tickets WHERE order_id = ?",
                (order_id,),
            ).rowcount
            conn.execute(
                "UPDATE orders SET status = 'cancelled' WHERE id = ?",
                (order_id,),
            )
    finally:
        conn.close()

    result = {
        "ok": True,
        "order_id": order_id,
        "tickets_voided": voided,
        "refund_id": refund.id,
        "refund_status": refund.status,
        "refunded_cents": amount,
        "full_refund": amount == order["total_cents"],
    }
    return result

import os

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ["STRIPE_SECRET_KEY"]
MAX_TICKETS_PER_ORDER = 10


@tool
def charge_ticket_purchase(customer_id: str, payment_method_id: str, event_id: str, quantity: int, unit_price_cents: int, currency: str = "usd") -> dict:
    if quantity < 1 or quantity > MAX_TICKETS_PER_ORDER:
        return {"ok": False, "error": f"quantity must be between 1 and {MAX_TICKETS_PER_ORDER}"}
    if unit_price_cents <= 0:
        return {"ok": False, "error": "unit_price_cents must be positive"}
    total = quantity * unit_price_cents
    try:
        intent = stripe.PaymentIntent.create(
            amount=total,
            currency=currency.lower(),
            customer=customer_id,
            payment_method=payment_method_id,
            off_session=True,
            confirm=True,
            description=f"{quantity} ticket(s) for event {event_id}",
            metadata={"event_id": event_id, "quantity": str(quantity)},
        )
    except stripe.error.CardError as exc:
        return {"ok": False, "error": exc.user_message or "card declined"}
    return {
        "ok": intent.status == "succeeded",
        "payment_intent_id": intent.id,
        "status": intent.status,
        "amount_cents": total,
        "currency": currency.lower(),
    }
